{"command": "mkdir -p /workspace/src && cat > /workspace/src/crypto.rs <<'EOF'
//! Cryptographic primitives needed by the password finder.
//!
//! Everything here is implemented from scratch so that the crate has no
//! third party dependencies: SHA-1 (used by HMAC/PBKDF2 for WinZip AES),
//! AES (128/192/256) in CTR mode, CRC-32 and the legacy "ZipCrypto"
//! stream cipher.

// ---------------------------------------------------------------------------
// CRC-32
// ---------------------------------------------------------------------------

fn crc32_table() -> [u32; 256] {
    let mut table = [0u32; 256];
    let mut i = 0usize;
    while i < 256 {
        let mut c = i as u32;
        let mut k = 0;
        while k < 8 {
            c = if c & 1 != 0 { 0xedb88320 ^ (c >> 1) } else { c >> 1 };
            k += 1;
        }
        table[i] = c;
        i += 1;
    }
    table
}

/// Streaming CRC-32 (the same polynomial as the ZIP format).
#[derive(Clone, Copy)]
pub struct Crc32 {
    state: u32,
}

impl Crc32 {
    pub fn new() -> Self {
        Crc32 { state: 0xffff_ffff }
    }

    pub fn update(&mut self, data: &[u8]) {
        let table = CRC_TABLE;
        for b in data {
            self.state = table[((self.state ^ (*b as u32)) & 0xff) as usize] ^ (self.state >> 8);
        }
    }

    pub fn finalize(&self) -> u32 {
        self.state ^ 0xffff_ffff
    }
}

impl Default for Crc32 {
    fn default() -> Self {
        Crc32::new()
    }
}

/// One-shot CRC-32 helper.
pub fn crc32(data: &[u8]) -> u32 {
    let mut c = Crc32::new();
    c.update(data);
    c.finalize()
}

/// Single byte update used by the legacy zip cipher (state is *not* inverted).
pub fn crc32_update(state: u32, byte: u8) -> u32 {
    (state >> 8) ^ CRC_TABLE[((state ^ byte as u32) & 0xff) as usize]
}

const CRC_TABLE: [u32; 256] = build_crc_table();

const fn build_crc_table() -> [u32; 256] {
    let mut table = [0u32; 256];
    let mut i = 0usize;
    while i < 256 {
        let mut c = i as u32;
        let mut k = 0;
        while k < 8 {
            c = if c & 1 != 0 { 0xedb88320 ^ (c >> 1) } else { c >> 1 };
            k += 1;
        }
        table[i] = c;
        i += 1;
    }
    table
}

// ---------------------------------------------------------------------------
// SHA-1
// ---------------------------------------------------------------------------

#[derive(Clone)]
pub struct Sha1 {
    h: [u32; 5],
    buffer: [u8; 64],
    buffered: usize,
    length: u64,
}

impl Sha1 {
    pub fn new() -> Self {
        Sha1 {
            h: [0x67452301, 0xefcdab89, 0x98badcfe, 0x10325476, 0xc3d2e1f0],
            buffer: [0u8; 64],
            buffered: 0,
            length: 0,
        }
    }

    pub fn digest(data: &[u8]) -> [u8; 20] {
        let mut s = Sha1::new();
        s.update(data);
        s.finalize()
    }

    fn compress(&mut self, block: &[u8]) {
        let mut w = [0u32; 80];
        let mut i = 0usize;
        while i < 16 {
            w[i] = u32::from_be_bytes([
                block[i * 4],
                block[i * 4 + 1],
                block[i * 4 + 2],
                block[i * 4 + 3],
            ]);
            i += 1;
        }
        while i < 80 {
            w[i] = (w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16]).rotate_left(1);
            i += 1;
        }
        let mut a = self.h[0];
        let mut b = self.h[1];
        let mut c = self.h[2];
        let mut d = self.h[3];
        let mut e = self.h[4];
        let mut t = 0usize;
        while t < 80 {
            let (f, k) = match t {
                0..=19 => ((b & c) | ((!b) & d), 0x5a82_7999u32),
                20..=39 => (b ^ c ^ d, 0x6ed9_eba1u32),
                40..=59 => ((b & c) | (b & d) | (c & d), 0x8fbb_cdcdu32),
                _ => (b ^ c ^ d, 0xca62_c1d6u32),
            };
            let tmp = a
                .rotate_left(5)
                .wrapping_add(f)
                .wrapping_add(e)
                .wrapping_add(k)
                .wrapping_add(w[t]);
            e = d;
            d = c;
            c = b.rotate_left(30);
            b = a;
            a = tmp;
            t += 1;
        }
        self.h[0] = self.h[0].wrapping_add(a);
        self.h[1] = self.h[1].wrapping_add(b);
        self.h[2] = self.h[2].wrapping_add(c);
        self.h[3] = self.h[3].wrapping_add(d);
        self.h[4] = self.h[4].wrapping_add(e);
    }

    pub fn update(&mut self, mut data: &[u8]) {
        self.length = self.length.wrapping_add(data.len() as u64);
        if self.buffered > 0 {
            let need = 64 - self.buffered;
            let take = need.min(data.len());
            self.buffer[self.buffered..self.buffered + take].copy_from_slice(&data[..take]);
            self.buffered += take;
            data = &data[take..];
            if self.buffered == 64 {
                let block = self.buffer;
                self.compress(&block);
                self.buffered = 0;
            }
        }
        while data.len() >= 64 {
            let (block, rest) = data.split_at(64);
            self.compress(block);
            data = rest;
        }
        if !data.is_empty() {
            self.buffer[..data.len()].copy_from_slice(data);
            self.buffered = data.len();
        }
    }

    pub fn finalize(mut self) -> [u8; 20] {
        let bit_len = self.length.wrapping_mul(8);
        let mut pad = [0u8; 72];
        pad[0] = 0x80;
        let rem = (self.length % 64) as usize;
        let pad_len = if rem < 56 { 56 - rem } else { 120 - rem };
        let total = pad_len + 8;
        let be = bit_len.to_be_bytes();
        pad[pad_len..pad_len + 8].copy_from_slice(&be);
        // update() would bump `length`, but we are done with it.
        let saved = self.length;
        let mut tail = Vec::with_capacity(total);
        tail.extend_from_slice(&pad[..total]);
        self.length = saved;
        // Manual padding to avoid touching `length`.
        if self.buffered + total > 64 {
            let need = 64 - self.buffered;
            self.buffer[self.buffered..64].copy_from_slice(&tail[..need]);
            let block = self.buffer;
            self.compress(&block);
            let rest = &tail[need..];
            let mut buf = [0u8; 64];
            buf[..rest.len()].copy_from_slice(rest);
            self.compress(&buf);
        } else {
            self.buffer[self.buffered..self.buffered + total].copy_from_slice(&tail[..total]);
            let block = self.buffer;
            self.compress(&block);
        }
        let mut out = [0u8; 20];
        for i in 0..5 {
            out[i * 4..i * 4 + 4].copy_from_slice(&self.h[i].to_be_bytes());
        }
        out
    }
}

impl Default for Sha1 {
    fn default() -> Self {
        Sha1::new()
    }
}

// ---------------------------------------------------------------------------
// HMAC-SHA1
// ---------------------------------------------------------------------------

#[derive(Clone)]
pub struct HmacSha1 {
    inner: Sha1,
    outer: Sha1,
}

impl HmacSha1 {
    pub fn new(key: &[u8]) -> Self {
        let mut block = [0u8; 64];
        if key.len() > 64 {
            let d = Sha1::digest(key);
            block[..20].copy_from_slice(&d);
        } else {
            block[..key.len()].copy_from_slice(key);
        }
        let mut ipad = [0u8; 64];
        let mut opad = [0u8; 64];
        for i in 0..64 {
            ipad[i] = block[i] ^ 0x36;
            opad[i] = block[i] ^ 0x5c;
        }
        let mut inner = Sha1::new();
        inner.update(&ipad);
        let mut outer = Sha1::new();
        outer.update(&opad);
        HmacSha1 { inner, outer }
    }

    pub fn update(&mut self, data: &[u8]) {
        self.inner.update(data);
    }

    pub fn finalize(mut self) -> [u8; 20] {
        let inner = self.inner.finalize();
        self.outer.update(&inner);
        self.outer.finalize()
    }

    pub fn verify_slice(self, expected: &[u8]) -> bool {
        let mac = self.finalize();
        let n = expected.len().min(20);
        if expected.len() > 20 {
            return false;
        }
        let mut diff = 0u8;
        for i in 0..n {
            diff |= mac[i] ^ expected[i];
        }
        diff == 0
    }
}

/// PBKDF2-HMAC-SHA1 with the requested output length.
pub fn pbkdf2_sha1(password: &[u8], salt: &[u8], iterations: u32, dk_len: usize) -> Vec<u8> {
    let mut mac = HmacSha1::new(password);
    mac.update(salt);
    let block = mac.finalize();
    let mut out = Vec::with_capacity(dk_len);
    let mut u = block;
    let mut block_index = 1u32;
    while out.len() < dk_len {
        let mut mac = HmacSha1::new(password);
        mac.update(salt);
        mac.update(&block_index.to_be_bytes());
        u = mac.finalize();
        let mut t = u;
        let mut i = 1;
        while i < iterations {
            let mut mac = HmacSha1::new(password);
            mac.update(&u);
            u = mac.finalize();
            for j in 0..20 {
                t[j] ^= u[j];
            }
            i += 1;
        }
        let take = (dk_len - out.len()).min(20);
        out.extend_from_slice(&t[..take]);
        block_index += 1;
    }
    out
}

