fn xt(a: u8) -> u8 {
    let a = a as u16;
    let a = a << 1;
    if a & 0x100 != 0 {
        (a ^ 0x11b) as u8
    } else {
        a as u8
    }
}

fn gmul(a: u8, b: u8) -> u8 {
    let mut a = a;
    let mut b = b;
    let mut r = 0u8;
    while b != 0 {
        if b & 1 != 0 {
            r ^= a;
        }
        b >>= 1;
        a = xt(a);
    }
    r
}

pub struct Aes {
    round_keys: Vec<[u8; 16]>,
    rounds: usize,
}

impl Aes {
    pub fn new(key: &[u8]) -> Aes {
        let nk = key.len() / 4;
        let rounds = nk + 6;
        let mut w: Vec<[u8; 4]> = Vec::with_capacity(4 * (rounds + 1));
        let mut i = 0usize;
        while i < nk {
            let mut word = [0u8; 4];
            word.copy_from_slice(&key[i * 4..i * 4 + 4]);
            w.push(word);
            i += 1;
        }
        while w.len() < 4 * (rounds + 1) {
            let i = w.len();
            let mut t = w[i - 1];
            if i % nk == 0 {
                t = [t[1], t[2], t[3], t[0]];
                for b in t.iter_mut() {
                    *b = SBOX[*b as usize];
                }
                t[0] ^= RCON[i / nk - 1];
            } else if nk > 6 && i % nk == 4 {
                for b in t.iter_mut() {
                    *b = SBOX[*b as usize];
                }
            }
            let prev = w[i - nk];
            w.push([
                prev[0] ^ t[0],
                prev[1] ^ t[1],
                prev[2] ^ t[2],
                prev[3] ^ t[3],
            ]);
        }
        let mut round_keys = Vec::with_capacity(rounds + 1);
        let mut r = 0usize;
        while r <= rounds {
            let mut block = [0u8; 16];
            for c in 0..4 {
                for row in 0..4 {
                    block[c * 4 + row] = w[r * 4 + c][row];
                }
            }
            round_keys.push(block);
            r += 1;
        }
        Aes { round_keys, rounds }
    }

    pub fn encrypt_block(&self, input: &[u8; 16]) -> [u8; 16] {
        let mut s = [0u8; 16];
        for c in 0..4 {
            for r in 0..4 {
                s[c * 4 + r] = input[c * 4 + r] ^ self.round_keys[0][c * 4 + r];
            }
        }
        let mut round = 1usize;
        while round <= self.rounds {
            for b in s.iter_mut() {
                *b = SBOX[*b as usize];
            }
            let old = s;
            for c in 0..4 {
                for r in 1..4 {
                    s[c * 4 + r] = old[((c + r) % 4) * 4 + r];
                }
            }
            if round != self.rounds {
                let old = s;
                for c in 0..4 {
                    let a0 = old[c * 4];
                    let a1 = old[c * 4 + 1];
                    let a2 = old[c * 4 + 2];
                    let a3 = old[c * 4 + 3];
                    s[c * 4] = xt(a0) ^ gmul(3, a1) ^ a2 ^ a3;
                    s[c * 4 + 1] = a0 ^ xt(a1) ^ gmul(3, a2) ^ a3;
                    s[c * 4 + 2] = a0 ^ a1 ^ xt(a2) ^ gmul(3, a3);
                    s[c * 4 + 3] = gmul(3, a0) ^ a1 ^ a2 ^ xt(a3);
                }
            }
            for c in 0..4 {
                for r in 0..4 {
                    s[c * 4 + r] ^= self.round_keys[round][c * 4 + r];
                }
            }
            round += 1;
        }
        s
    }

    /// AES-CTR keystream generator.
    pub fn ctr(&self, iv: [u8; 16], data: &mut [u8]) {
        let mut counter = iv;
        let mut offset = 0usize;
        while offset < data.len() {
            let ks = self.encrypt_block(&counter);
            let n = (data.len() - offset).min(16);
            for i in 0..n {
                data[offset + i] ^= ks[i];
            }
            offset += n;
            // increment the 128 bit big endian counter
            for i in (0..16).rev() {
                if counter[i] == 0xff {
                    counter[i] = 0;
                } else {
                    counter[i] += 1;
                    break;
                }
            }
        }
    }
}

