#[derive(Clone)]
pub struct HmacSha1 {
    inner: Sha1,
    outer: Sha1,
}

impl HmacSha1 {
    pub fn new(key: &[u8]) -> Self {
        let mut block = [0u8; 64];
        if key.len() > 64 {
            let d = Sha1::digest(key);
            block[..20].copy_from_slice(&d);
        } else {
            block[..key.len()].copy_from_slice(key);
        }
        let mut ipad = [0u8; 64];
        let mut opad = [0u8; 64];
        for i in 0..64 {
            ipad[i] = block[i] ^ 0x36;
            opad[i] = block[i] ^ 0x5c;
        }
        let mut inner = Sha1::new();
        inner.update(&ipad);
        let mut outer = Sha1::new();
        outer.update(&opad);
        HmacSha1 { inner, outer }
    }

    pub fn update(&mut self, data: &[u8]) {
        self.inner.update(data);
    }

    pub fn finalize(mut self) -> [u8; 20] {
        let inner = self.inner.finalize();
        self.outer.update(&inner);
        self.outer.finalize()
    }

    pub fn verify_slice(self, expected: &[u8]) -> bool {
        let mac = self.finalize();
        let n = expected.len().min(20);
        if expected.len() > 20 {
            return false;
        }
        let mut diff = 0u8;
        for i in 0..n {
            diff |= mac[i] ^ expected[i];
        }
        diff == 0
    }
}

/// PBKDF2-HMAC-SHA1 with the requested output length.
pub fn pbkdf2_sha1(password: &[u8], salt: &[u8], iterations: u32, dk_len: usize) -> Vec<u8> {
    let mut mac = HmacSha1::new(password);
    mac.update(salt);
    let block = mac.finalize();
    let mut out = Vec::with_capacity(dk_len);
    let mut u = block;
    let mut block_index = 1u32;
    while out.len() < dk_len {
        let mut mac = HmacSha1::new(password);
        mac.update(salt);
        mac.update(&block_index.to_be_bytes());
        u = mac.finalize();
        let mut t = u;
        let mut i = 1;
        while i < iterations {
            let mut mac = HmacSha1::new(password);
            mac.update(&u);
            u = mac.finalize();
            for j in 0..20 {
                t[j] ^= u[j];
            }
            i += 1;
        }
        let take = (dk_len - out.len()).min(20);
        out.extend_from_slice(&t[..take]);
        block_index += 1;
    }
    out
}

