        Aes { round_keys, rounds }
    }

    pub fn encrypt_block(&self, input: &[u8; 16]) -> [u8; 16] {
        let mut s = [0u8; 16];
        for c in 0..4 {
            for r in 0..4 {
                s[c * 4 + r] = input[c * 4 + r] ^ self.round_keys[0][c * 4 + r];
            }
        }
        let mut round = 1usize;
        while round <= self.rounds {
            for b in s.iter_mut() {
                *b = SBOX[*b as usize];
            }
            let old = s;
            for c in 0..4 {
                for r in 1..4 {
                    s[c * 4 + r] = old[((c + r) % 4) * 4 + r];
                }
            }
            if round != self.rounds {
                let old = s;
                for c in 0..4 {
                    let a0 = old[c * 4];
                    let a1 = old[c * 4 + 1];
                    let a2 = old[c * 4 + 2];
                    let a3 = old[c * 4 + 3];
                    s[c * 4] = xt(a0) ^ gmul(3, a1) ^ a2 ^ a3;
                    s[c * 4 + 1] = a0 ^ xt(a1) ^ gmul(3, a2) ^ a3;
                    s[c * 4 + 2] = a0 ^ a1 ^ xt(a2) ^ gmul(3, a3);
                    s[c * 4 + 3] = gmul(3, a0) ^ a1 ^ a2 ^ xt(a3);
                }
            }
            for c in 0..4 {
                for r in 0..4 {
                    s[c * 4 + r] ^= self.round_keys[round][c * 4 + r];
                }
            }
            round += 1;
        }
        s
    }

    /// AES-CTR keystream generator.
    pub fn ctr(&self, iv: [u8; 16], data: &mut [u8]) {
        let mut counter = iv;
        let mut offset = 0usize;
        while offset < data.len() {
            let ks = self.encrypt_block(&counter);
            let n = (data.len() - offset).min(16);
            for i in 0..n {
                data[offset + i] ^= ks[i];
            }
            offset += n;
            // increment the 128 bit big endian counter
            for i in (0..16).rev() {
                if counter[i] == 0xff {
                    counter[i] = 0;
                } else {
                    counter[i] += 1;
                    break;
                }
            }
        }
    }
}

const RCON: [u8; 14] = [
    0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0x1b, 0x36, 0x6c, 0xd8, 0xab, 0x4d,
];

// ---------------------------------------------------------------------------
// Legacy zip cipher ("ZipCrypto")
// ---------------------------------------------------------------------------

#[derive(Clone)]
pub struct ZipCrypto {
    key0: u32,
    key1: u32,
    key2: u32,
}

impl ZipCrypto {
    pub fn new(password: &[u8]) -> Self {
        let mut c = ZipCrypto {
            key0: 0x1234_5678,
            key1: 0x2345_6789,
            key2: 0x3456_7890,
        };
        for b in password {
            c.update(*b);
        }
        c
    }

    fn update(&mut self, byte: u8) {
        self.key0 = crc32_update(self.key0, byte);
        self.key1 = self
            .key1
            .wrapping_add(self.key0 & 0xff)
            .wrapping_mul(134775813)
            .wrapping_add(1);
        self.key2 = crc32_update(self.key2, (self.key1 >> 24) as u8);
    }

    fn stream_byte(&self) -> u8 {
        let t = self.key2 | 2;
        ((t.wrapping_mul(t ^ 1)) >> 8) as u8
    }

    pub fn decrypt(&mut self, data: &mut [u8]) {
        for b in data.iter_mut() {
            let p = *b ^ self.stream_byte();
            self.update(p);
            *b = p;
        }
    }

    pub fn encrypt(&mut self, data: &mut [u8]) {
        for b in data.iter_mut() {
            let c = *b ^ self.stream_byte();
            self.update(*b);
            *b = c;
        }
    }
}
