];

/// Rendered command line option as clap prints it inside errors, e.g.
/// `--inputFile <inputFile>`.
fn invocation(spec: &Spec) -> String {
    format!("--{} <{}>", spec.long, spec.value_name)
}

fn bin_name() -> String {
    std::env::args_os()
        .next()
        .map(|a| {
            std::path::Path::new(&a)
                .file_name()
                .map(|f| f.to_string_lossy().to_string())
                .unwrap_or_else(|| a.to_string_lossy().to_string())
        })
        .unwrap_or_else(|| "zip-password-finder".to_string())
}

pub fn help_text() -> String {
    let mut out = String::new();
    out.push_str(ABOUT);
    out.push('\n');
    out.push('\n');
    out.push_str(&format!(
        "Usage: {} [OPTIONS] --inputFile <inputFile>\n",
        bin_name()
    ));
    out.push('\n');
    out.push_str("Options:\n");
    // clap aligns the help column: 2 spaces + option, then pad to the widest
    let mut rows: Vec<(String, String)> = Vec::new();
    for spec in SPECS {
        let left = match spec.short {
            Some(c) => format!("  -{}, --{} <{}>", c, spec.long, spec.value_name),
            None => format!("      --{} <{}>", spec.long, spec.value_name),
        };
        let mut right = spec.help.to_string();
        if let Some(d) = spec.default {
            right.push_str(&format!(" [default: {}]", d));
        }
        rows.push((left, right));
    }
    rows.push(("  -h, --help".to_string(), "Print help".to_string()));
    rows.push(("  -V, --version".to_string(), "Print version".to_string()));
