pub enum ParseOutcome {
    Parsed(ParsedArgs),
    Help,
    Version,
    Error(String),
}

#[derive(Default)]
pub struct ParsedArgs {
    pub input_file: Option<String>,
    pub workers: Option<String>,
    pub dictionary: Option<String>,
    pub charset: Option<String>,
    pub charset_file: Option<String>,
    pub min_len: Option<String>,
    pub max_len: Option<String>,
    pub file_number: Option<String>,
    pub start: Option<String>,
}

pub fn parse(argv: &[String]) -> ParseOutcome {
    let mut values = ParsedArgs::default();
    let mut seen: Vec<ArgId> = Vec::new();
    let mut i = 0usize;
    let mut positional_only = false;
    while i < argv.len() {
        let arg = argv[i].clone();
        if positional_only {
            return ParseOutcome::Error(unexpected(&arg));
        }
        if arg == "--" {
            positional_only = true;
            i += 1;
            continue;
        }
        if arg == "--help" {
            return ParseOutcome::Help;
        }
        if arg == "--version" {
            return ParseOutcome::Version;
        }
        if arg.starts_with("--") {
            let body = &arg[2..];
            let (name, inline) = match body.find('=') {
                Some(p) => (&body[..p], Some(body[p + 1..].to_string())),
                None => (body, None),
            };
            let spec = SPECS.iter().find(|s| s.long == name);
            match spec {
                None => return ParseOutcome::Error(unexpected(&arg)),
                Some(spec) => {
                    let value = match inline {
                        Some(v) => Some(v),
                        None => {
                            i += 1;
                            if i >= argv.len() {
                                return ParseOutcome::Error(missing_value(spec));
                            }
                            let v = argv[i].clone();
                            if v.starts_with('-') && v.len() > 1 && is_flagish(&v) {
                                return ParseOutcome::Error(missing_value(spec));
                            }
                            Some(v)
                        }
                    };
                    if let Err(e) = store(spec, value.unwrap(), &mut values, &mut seen) {
                        return ParseOutcome::Error(e);
                    }
                }
            }
            i += 1;
            continue;
        }
        if arg.starts_with('-') && arg.len() > 1 {
            // short option(s), possibly with an attached value
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut idx = 0usize;
            while idx < chars.len() {
                let c = chars[idx];
                if c == 'h' {
                    return ParseOutcome::Help;
                }
                if c == 'V' {
                    return ParseOutcome::Version;
                }
                let spec = SPECS.iter().find(|s| s.short == Some(c));
                match spec {
                    None => {
                        return ParseOutcome::Error(unexpected(&format!("-{}", c)));
                    }
                    Some(spec) => {
                        let rest: String = chars[idx + 1..].iter().collect();
                        let value = if !rest.is_empty() {
                            let r = rest.strip_prefix('=').map(|s| s.to_string()).unwrap_or(rest);
                            Some(r)
                        } else {
                            i += 1;
                            if i >= argv.len() {
                                return ParseOutcome::Error(missing_value(spec));
                            }
                            let v = argv[i].clone();
                            if v.starts_with('-') && v.len() > 1 && is_flagish(&v) {
                                return ParseOutcome::Error(missing_value(spec));
                            }
                            Some(v)
                        };
                        if let Err(e) = store(spec, value.unwrap(), &mut values, &mut seen) {
                            return ParseOutcome::Error(e);
                        }
                        idx = chars.len();
                    }
                }
            }
            i += 1;
            continue;
        }
        return ParseOutcome::Error(unexpected(&arg));
    }
    if !values.input_file.is_some() {
        let mut msg = String::from("error: the following required arguments were not provided:\n");
        for spec in SPECS {
            if spec.required && !seen.contains(&spec.id) {
                msg.push_str(&format!("  {}\n", invocation(spec)));
            }
        }
        msg.push('\n');
        msg.push_str(&format!("Usage: {} --inputFile <inputFile>\n", bin_name()));
        msg.push('\n');
        msg.push_str("For more information, try '--help'.\n");
        return ParseOutcome::Error(msg);
    }
    ParseOutcome::Parsed(values)
}

fn is_flagish(v: &str) -> bool {
    // clap only treats a following `-x` token as an option when it is not a
    // negative number that the value type could accept.
    let body = &v[1..];
    if body.is_empty() {
        return true;
    }
    let mut chars = body.chars();
    let first = chars.next().unwrap();
    if first.is_ascii_digit() {
        return false;
    }
    true
}

fn unexpected(arg: &str) -> String {
    let mut msg = format!("error: unexpected argument '{}' found\n", arg);
    msg.push('\n');
    msg.push_str(&format!(
        "Usage: {} [OPTIONS] --inputFile <inputFile>\n",
        bin_name()
    ));
    msg.push('\n');
    msg.push_str("For more information, try '--help'.\n");
    msg
}

fn missing_value(spec: &Spec) -> String {
    let mut msg = format!(
        "error: a value is required for '{}' but none was supplied\n",
        invocation(spec)
    );
    msg.push('\n');
    msg.push_str("For more information, try '--help'.\n");
    msg
}

fn store(
    spec: &Spec,
    value: String,
    out: &mut ParsedArgs,
    seen: &mut Vec<ArgId>,
) -> Result<(), String> {
    if seen.contains(&spec.id) {
        let mut msg = format!(
            "error: the argument '{}' cannot be used multiple times\n",
            invocation(spec)
        );
        msg.push('\n');
        msg.push_str(&format!(
            "Usage: {} [OPTIONS] --inputFile <inputFile>\n",
            bin_name()
        ));
        msg.push('\n');
        msg.push_str("For more information, try '--help'.\n");
        return Err(msg);
    }
    seen.push(spec.id);
    if spec.kind == Kind::Num {
        if let Err(e) = value.parse::<usize>() {
            let mut msg = format!(
                "error: invalid value '{}' for '{}': {}\n",
                value,
                invocation(spec),
                parse_int_error(&value)
            );
            msg.push('\n');
            msg.push_str("For more information, try '--help'.\n");
            let _ = e;
            return Err(msg);
        }
    }
    match spec.id {
        ArgId::InputFile => out.input_file = Some(value),
        ArgId::Workers => out.workers = Some(value),
        ArgId::Dictionary => out.dictionary = Some(value),
        ArgId::Charset => out.charset = Some(value),
        ArgId::CharsetFile => out.charset_file = Some(value),
        ArgId::MinLen => out.min_len = Some(value),
        ArgId::MaxLen => out.max_len = Some(value),
        ArgId::FileNumber => out.file_number = Some(value),
        ArgId::Start => out.start = Some(value),
    }
    Ok(())
}

/// Reproduces `std::num::ParseIntError` messages.
fn parse_int_error(value: &str) -> &'static str {
    if value.is_empty() {
        return "cannot parse integer from empty string";
    }
    let body = if let Some(r) = value.strip_prefix('+') {
        r
    } else if let Some(r) = value.strip_prefix('-') {
        r
    } else {
        value
    };
    if body.is_empty() {
        return "cannot parse integer from empty string";
    }
    if !body.chars().all(|c| c.is_ascii_digit()) {
        return "invalid digit found in string";
    }
    "number too large to fit in target type"
}
