{"command": "cat > /workspace/src/zip.rs <<'RSEOF'
//! Very small ZIP reader: just enough to locate one entry of an archive and
//! to produce the same error strings as the archive library the original
//! program relied on.

use crate::crypto::crc32_update;

#[derive(Debug)]
pub enum ZipError {
    InvalidArchive(String),
    Io(String),
}

impl std::fmt::Display for ZipError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ZipError::InvalidArchive(m) => write!(f, "invalid Zip archive: {}", m),
            ZipError::Io(m) => write!(f, "i/o error: {}", m),
        }
    }
}

pub const EOCD_SIG: u32 = 0x0605_4b50;
pub const CDFH_SIG: u32 = 0x0201_4b50;
pub const LFH_SIG: u32 = 0x0403_4b50;

pub struct Entry {
    pub name: String,
    pub flags: u16,
    pub method: u16,
    pub crc: u32,
    pub compressed_size: u64,
    pub uncompressed_size: u64,
    pub local_offset: u64,
    pub extra: Vec<u8>,
    pub version_needed: u16,
}

pub struct Archive {
    pub data: Vec<u8>,
    pub entries: Vec<Entry>,
}

fn u16_at(d: &[u8], o: usize) -> u16 {
    u16::from_le_bytes([d[o], d[o + 1]])
}

fn u32_at(d: &[u8], o: usize) -> u32 {
    u32::from_le_bytes([d[o], d[o + 1], d[o + 2], d[o + 3]])
}

impl Archive {
    pub fn open(path: &str) -> Result<Archive, ZipError> {
        let data = match std::fs::read(path) {
            Ok(d) => d,
            Err(e) => return Err(ZipError::Io(e.to_string())),
        };
        Archive::parse(data)
    }

    pub fn parse(data: Vec<u8>) -> Result<Archive, ZipError> {
        let len = data.len();
        if len < 22 {
            return Err(ZipError::InvalidArchive("Could not find EOCD".to_string()));
        }
        // scan backwards for the EOCD signature
        let start = len.saturating_sub(22 + 65535);
        let mut eocd_pos: Option<usize> = None;
        let mut i = len - 22;
        loop {
            if u32_at(&data, i) == EOCD_SIG {
                // the comment length must match the remaining bytes
                let comment_len = u16_at(&data, i + 20) as usize;
                if i + 22 + comment_len == len {
                    eocd_pos = Some(i);
                    break;
                }
            }
            if i == start {
                break;
            }
            i -= 1;
        }
        let eocd_pos = match eocd_pos {
            Some(p) => p,
            None => return Err(ZipError::InvalidArchive("Could not find EOCD".to_string())),
        };
        let count = u16_at(&data, eocd_pos + 10) as usize;
        let cd_size = u32_at(&data, eocd_pos + 12) as usize;
        let cd_offset = u32_at(&data, eocd_pos + 16) as usize;
        if count == 0 {
            // matches the behaviour of the archive reader used originally
            return Err(ZipError::InvalidArchive(
                "Unexpected end of zip::spec::Zip32CDEBlock".to_string(),
            ));
        }
        if cd_offset > len {
            return Err(ZipError::InvalidArchive(
                "Invalid CDFH offset in EOCD".to_string(),
            ));
        }
        let mut entries: Vec<Entry> = Vec::with_capacity(count);
        let mut pos = cd_offset;
        let mut index = 0usize;
        while index < count {
            if pos + 46 > len {
                return Err(ZipError::InvalidArchive(
                    "Unexpected end of zip::spec::Zip32CDEBlock".to_string(),
                ));
            }
            if u32_at(&data, pos) != CDFH_SIG {
                return Err(ZipError::InvalidArchive("No CDFH found".to_string()));
            }
            let version_needed = u16_at(&data, pos + 6);
            let flags = u16_at(&data, pos + 8);
            let method = u16_at(&data, pos + 10);
            let crc = u32_at(&data, pos + 16);
            let compressed_size = u32_at(&data, pos + 20) as u64;
            let uncompressed_size = u32_at(&data, pos + 24) as u64;
            let name_len = u16_at(&data, pos + 28) as usize;
            let extra_len = u16_at(&data, pos + 30) as usize;
            let comment_len = u16_at(&data, pos + 32) as usize;
            let local_offset = u32_at(&data, pos + 42) as u64;
            if pos + 46 + name_len + extra_len + comment_len > len {
                return Err(ZipError::InvalidArchive(
                    "Unexpected end of zip::spec::Zip32CDEBlock".to_string(),
                ));
            }
            let name_bytes = &data[pos + 46..pos + 46 + name_len];
            let name = decode_name(name_bytes);
            let extra = data[pos + 46 + name_len..pos + 46 + name_len + extra_len].to_vec();
            entries.push(Entry {
                name,
                flags,
                method,
                crc,
                compressed_size,
                uncompressed_size,
                local_offset,
                extra,
                version_needed,
            });
            pos += 46 + name_len + extra_len + comment_len;
            index += 1;
        }
        Ok(Archive { data, entries })
    }

    /// Locate the payload of `entry` inside the archive, validating the local
    /// file header the same way the original program did.
    pub fn payload(&self, index: usize) -> Result<Vec<u8>, ZipError> {
        let entry = &self.entries[index];
        let off = entry.local_offset as usize;
        let data = &self.data;
        if off + 30 > data.len() || u32_at(data, off) != LFH_SIG {
            return Err(ZipError::InvalidArchive(
                "Invalid local file header".to_string(),
            ));
        }
        let name_len = u16_at(data, off + 26) as usize;
        let extra_len = u16_at(data, off + 28) as usize;
        let start = off + 30 + name_len + extra_len;
        let end = match start.checked_add(entry.compressed_size as usize) {
            Some(e) => e,
            None => {
                return Err(ZipError::InvalidArchive(
                    "Invalid local file header".to_string(),
                ))
            }
        };
        if end > data.len() {
            return Err(ZipError::Io(
                "failed to fill whole buffer".to_string(),
            ));
        }
        Ok(data[start..end].to_vec())
    }

    /// Local header fields (the local header may differ from the central one).
    pub fn local_fields(&self, index: usize) -> Option<(u16, u16, u32, u64, u64, usize)> {
        let entry = &self.entries[index];
        let off = entry.local_offset as usize;
        let data = &self.data;
        if off + 30 > data.len() || u32_at(data, off) != LFH_SIG {
            return None;
        }
        Some((
            u16_at(data, off + 6),
            u16_at(data, off + 8),
            u32_at(data, off + 14),
            u32_at(data, off + 18) as u64,
            u32_at(data, off + 22) as u64,
            u16_at(data, off + 28) as usize,
        ))
    }
}

fn decode_name(bytes: &[u8]) -> String {
    // the archives used by the tool are all UTF-8 / ASCII
    match std::str::from_utf8(bytes) {
        Ok(s) => s.to_string(),
        Err(_) => String::from_utf_lossy(bytes).to_string(),
    }
}

/// AES extra field (id 0x9901) as written by WinZip compatible tools.
pub struct AesExtra {
    pub strength: u8,
    pub method: u16,
}

pub fn parse_aes_extra(extra: &[u8]) -> Result<AesExtra, ZipError> {
    let mut pos = 0usize;
    while pos + 4 <= extra.len() {
        let id = u16_at(extra, pos);
        let size = u16_at(extra, pos + 2) as usize;
        if id == 0x9901 {
            if pos + 4 + size > extra.len() || size < 7 {
                return Err(ZipError::InvalidArchive(
                    "Extra field content truncated".to_string(),
                ));
            }
            let body = &extra[pos + 4..pos + 4 + size];
            let strength = body[4];
            let method = u16_at(body, 5);
            if !(1..=3).contains(&strength) {
                return Err(ZipError::InvalidArchive(
                    "Extra field content truncated".to_string(),
                ));
            }
            return Ok(AesExtra { strength, method });
        }
        pos += 4 + size;
    }
    Err(ZipError::InvalidArchive(
        "AES encryption without AES extra data field".to_string(),
