//! Candidate password generator.
//!
//! Candidates are enumerated by an absolute index inside the search space
//! formed by every string of length `minPasswordLen..=maxPasswordLen` built
//! over the (deduplicated, sorted) charset.

/// Expands the charset specifiers (`l`, `u`, `d`, `h`, `H`, `s`) into the
/// characters they stand for.
fn named_charset(option: char) -> Option<&'static str> {
    match option {
        'l' => Some("abcdefghijklmnopqrstuvwxyz"),
        'u' => Some("ABCDEFGHIJKLMNOPQRSTUVWXYZ"),
        'd' => Some("0123456789"),
        'h' => Some("0123456789abcdef"),
        'H' => Some("0123456789ABCDEF"),
        's' => Some(" !\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~"),
        _ => None,
    }
}

/// Builds the charset from a specification string, returning the offending
/// character when the option is unknown.
pub fn charset_from_options(options: &str) -> Result<Vec<char>, char> {
    let mut collected: Vec<char> = Vec::new();
    for option in options.chars() {
        match named_charset(option) {
            Some(chars) => collected.extend(chars.chars()),
            None => return Err(option),
        }
    }
    Ok(dedup_sorted(collected))
}

/// Builds the charset from the raw contents of a charset file.
pub fn charset_from_file(contents: &str) -> Vec<char> {
    dedup_sorted(contents.chars().collect())
}

/// Removes duplicates keeping the set sorted by code point, which is the
/// order in which candidates are generated.
fn dedup_sorted(chars: Vec<char>) -> Vec<char> {
    let mut set: Vec<char> = Vec::with_capacity(chars.len());
    for c in chars {
        if !set.contains(&c) {
            set.push(c);
        }
    }
    set.sort();
    set
}

pub struct PasswordGen {
    charset: Vec<char>,
    min_len: usize,
    max_len: usize,
    counts: Vec<u128>,
    offsets: Vec<u128>,
    total: u128,
}

impl PasswordGen {
    pub fn new(charset: Vec<char>, min_len: usize, max_len: usize) -> PasswordGen {
        let mut counts: Vec<u128> = Vec::new();
        let base = charset.len() as u128;
        let mut length = min_len;
        while length <= max_len {
            counts.push(pow_u128(base, length as u32));
            length += 1;
        }
        let mut offsets: Vec<u128> = Vec::with_capacity(counts.len());
        let mut acc = 0u128;
        for c in counts.iter() {
            offsets.push(acc);
            acc = acc.saturating_add(*c);
        }
        let gen = PasswordGen {
            charset,
            min_len,
            max_len,
            counts,
            offsets,
            total: acc,
        };
        // The charset has to contain at least one character, otherwise there is
        // nothing to enumerate.
        let first_char = gen.charset.get(0).expect("charset non empty");
        let _ = first_char;
        gen
    }

    pub fn total(&self) -> u128 {
        self.total
    }

    pub fn charset(&self) -> &[char] {
        &self.charset
    }

    pub fn min_len(&self) -> usize {
        self.min_len
    }

    pub fn max_len(&self) -> usize {
        self.max_len
    }

    /// Index of a password inside the enumeration, if it is representable.
    pub fn index_of(&self, password: &str) -> Option<u128> {
        let chars: Vec<char> = password.chars().collect();
        let len = chars.len();
        if len < self.min_len || len > self.max_len {
            return None;
        }
        for c in chars.iter() {
            if !self.charset.contains(c) {
                return None;
            }
        }
        let block = len - self.min_len;
        let base = self.charset.len() as u128;
        let mut within: u128 = 0;
        for c in chars.iter() {
            let idx = self.charset.iter().position(|x| x == c).unwrap() as u128;
            within = within * base + idx;
        }
        Some(self.offsets[block] + within)
    }

    /// Generates the candidate sitting at `index`.
    pub fn generate(&self, index: u128) -> String {
        let mut block = 0usize;
        while block + 1 < self.counts.len() && index >= self.offsets[block + 1] {
            block += 1;
        }
        let within = index - self.offsets[block];
        let len = self.min_len + block;
        let base = self.charset.len() as u128;
        let mut out = String::with_capacity(len);
        let mut remaining = within;
        let mut pos = len;
        while pos > 0 {
            pos -= 1;
            let digit = remaining % base;
            remaining /= base;
            out.insert(0, self.charset[digit as usize]);
        }
        out
    }

    /// Incrementally generates the candidate following `index` (used to avoid
    /// recomputing powers for every single candidate).
    pub fn generate_range(&self, start: u128, count: u128) -> Vec<String> {
        let mut out = Vec::with_capacity(count as usize);
        let mut index = start;
        let mut left = count;
        while left > 0 && index < self.total {
            out.push(self.generate(index));
            index += 1;
            left -= 1;
        }
        out
    }
}

fn pow_u128(base: u128, exp: u32) -> u128 {
    if base == 0 {
        return 0;
    }
    let mut result: u128 = 1;
    let mut b = base;
    let mut e = exp;
    while e > 0 {
        if e & 1 == 1 {
            result = result.saturating_mul(b);
        }
        b = b.saturating_mul(b);
        e >>= 1;
    }
    result
}
