//! Password verification for the two encryption flavours found in ZIP
//! archives: the legacy PKWARE cipher and WinZip AES.

use crate::crypto::{crc32, crc32_update, pbkdf2_sha1, Aes, Crc32, HmacSha1, ZipCrypto};
use crate::zip::{inflate, parse_aes_extra, ZipError};

/// Which algorithm the entry uses, derived from the archive metadata.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Encryption {
    ZipCrypto,
    Aes { strength: u8, method: u16 },
}

/// Everything needed to test candidate passwords against one entry.
pub struct Target {
    pub encryption: Encryption,
    pub crc: u32,
    pub compressed_size: u64,
    pub uncompressed_size: u64,
    pub compression_method: u16,
    pub payload: Vec<u8>,
}

impl Target {
    /// Parses the entry metadata into a verification target.
    pub fn build(
        flags: u16,
        method: u16,
        crc: u32,
        compressed_size: u64,
        uncompressed_size: u64,
        extra: &[u8],
        mut payload: Vec<u8>,
    ) -> Result<Target, ZipError> {
        let encryption = if method == 99 {
            let aes = parse_aes_extra(extra)?;
            Encryption::Aes { strength: aes.strength, method: aes.method }
        } else {
            Encryption::ZipCrypto
        };
        Ok(Target {
            encryption,
            crc,
            compressed_size,
            uncompressed_size,
            compression_method: method,
            payload,
        })
    }

    pub fn verify(&self, password: &[u8]) -> bool {
        match self.encryption {
            Encryption::ZipCrypto => self.verify_zipcrypto(password),
            Encryption::Aes { strength, .. } => self.verify_aes(password, strength),
        }
    }

    fn verify_zipcrypto(&self, password: &[u8]) -> bool {
        if self.payload.len() < 12 {
            return false;
        }
        let mut data = self.payload.clone();
        let mut cipher = ZipCrypto::new(password);
        cipher.decrypt(&mut data);
        if data[11] != ((self.crc >> 24) & 0xff) as u8 {
            return false;
        }
        let body = &data[12..];
        match self.compression_method {
            0 => crc32(body) == self.crc,
            8 => match inflate(body) {
                Some(plain) => crc32(&plain) == self.crc,
                None => false,
            },
            _ => false,
        }
    }

    fn verify_aes(&self, password: &[u8], strength: u8) -> bool {
        let key_len: usize = match strength {
            1 => 16,
            2 => 24,
            _ => 32,
        };
        let salt_len = key_len / 2;
        let data = &self.payload;
        if data.len() < salt_len + 2 + 10 {
            return false;
        }
        let salt = &data[..salt_len];
        let pv = &data[salt_len..salt_len + 2];
        let dk = pbkdf2_sha1(password, salt, 1000, 2 * key_len + 2);
        if dk[2 * key_len..] != pv[..] {
            return false;
        }
        let key = &dk[..key_len];
        let mac_key = &dk[key_len..2 * key_len];
        // The stored path uses the uncompressed size as the ciphertext length.
        let ct_len = if salt_len + 2 + self.uncompressed_size as usize + 10 <= data.len() {
            self.uncompressed_size as usize
        } else {
            data.len() - salt_len - 2 - 10
        };
        let ct = &data[salt_len + 2..salt_len + 2 + ct_len];
        let auth = &data[data.len() - 10..];
        if !HmacSha1::new(mac_key).verify_slice(auth) {
            // HMAC covers the ciphertext
            if !HmacSha1::new(mac_key)
                .verify_slice(ct)
            {
                return false;
            }
        }
        true
    }
}
