//! zip-password-finder: recovers the password of a protected ZIP archive.

mod args;
mod crypto;
mod duration;
mod password_gen;
mod verify;
mod zip;
mod zip_utils;

use args::{ArgId, ParsedArgs};
use password_gen::PasswordGen;
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::mpsc::RecvTimeoutError;
use std::sync::{mpsc, Arc};
use std::time::{Duration, Instant};
use verify::{Encryption, Target};
use zip::ZipError;

const DEFAULT_WORKERS: usize = 64;
const CANDIDATES_PER_UNIT: usize = 500;

/// Errors that are reported on stderr with a dedicated prefix and exit code 1.
enum Failure {
    Cli(String),
    Zip(ZipError),
    FileNumber(usize),
    Io(std::io::Error),
}

impl std::fmt::Display for Failure {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Failure::Cli(m) => write!(f, "CLI argument error - {}", m),
            Failure::Zip(e) => write!(f, "Invalid zip file error - {}", e),
            Failure::FileNumber(n) => write!(f, "File number not found within archive error - '{}'", n),
            Failure::Io(e) => write!(f, "standard I/O error - {}", e),
        }
    }
}

struct Config {
    input_file: String,
    workers: usize,
    dictionary: Option<String>,
    charset: Vec<char>,
    min_len: usize,
    max_len: usize,
    file_number: usize,
    start: Option<String>,
}

fn main() {
    let argv: Vec<String> = std::env::args().skip(1).collect();
    let started = Instant::now();
    match args::parse(&argv) {
        args::ParseOutcome::Help => {
            print!("{}", args::help_text());
        }
        args::ParseOutcome::Version => {
            println!("{}", args::VERSION);
        }
        args::ParseOutcome::Error(message) => {
            eprint!("{}", message);
            std::process::exit(2);
        }
        args::ParseOutcome::Parsed(parsed) => match run(parsed, started) {
            Ok(()) => {}
            Err(failure) => {
                eprintln!("{}", failure);
                std::process::exit(1);
            }
        },
    }
}

fn num_field(parsed: &ParsedArgs, id: ArgId) -> Option<usize> {
    let raw = match id {
        ArgId::Workers => parsed.workers.as_deref(),
        ArgId::MinLen => parsed.min_len.as_deref(),
        ArgId::MaxLen => parsed.max_len.as_deref(),
        ArgId::FileNumber => parsed.file_number.as_deref(),
        _ => None,
    }?;
    match raw.parse::<usize>() {
        Ok(v) => Some(v),
        Err(_) => None,
    }
}

fn run(parsed: ParsedArgs, started: Instant) -> Result<(), Failure> {
    let config = configure(&parsed)?;
    let reader = zip_utils::ZipReader::new(&config.input_file);
    let archive = zip::Archive::open(&config.input_file).map_err(Failure::Zip)?;
    if config.file_number >= archive.entries.len() {
        return Err(Failure::FileNumber(config.file_number));
    }
    let entry = &archive.entries[config.file_number];
    if entry.flags & 0x1 == 0 {
        return Err(Failure::Zip(ZipError::InvalidArchive(format!(
            "the selected file in the archive is not encrypted (file_number:{} file_name:{})",
            config.file_number, entry.name
        ))));
    }
    let payload = reader.payload(config.file_number).map_err(Failure::Zip)?;
    let local = reader
        .local_fields(config.file_number)
        .ok_or_else(|| Failure::Zip(ZipError::InvalidArchive("Invalid local file header".into())))?;
    let target = Target::build(
        entry.flags,
        local.1,
        local.2,
        local.3,
        local.4,
        &entry.extra,
        payload,
    )
    .map_err(Failure::Zip)?;
    let target = Arc::new(target);

    let outcome = match &config.dictionary {
        Some(path) => {
            let passwords = read_dictionary(path)?;
            search_dictionary(target, passwords, config.workers)
        }
        None => {
            let gen = Arc::new(PasswordGen::new(
                config.charset.clone(),
                config.min_len,
                config.max_len,
            ));
            let start_index = match &config.start {
                Some(sp) => gen.index_of(sp).unwrap_or(0),
                None => 0,
            };
            let end_index = match &config.start {
                Some(_) => {
                    let total = gen.total();
                    if start_index + 1 >= total {
