                    } else {
                        total - 1
                    }
                }
                None => gen.total(),
            };
            search_brute_force(
                target,
                gen,
                start_index,
                end_index,
                config.workers,
                config.min_len,
                config.max_len,
            )
        }
    };
    let elapsed = started.elapsed();
    println!("Time elapsed: {}", duration::format_duration(elapsed));
    match outcome {
        Some(password) => println!("Password found:{}", password),
        None => println!("Password not found"),
    }
    Ok(())
}

fn configure(parsed: &ParsedArgs) -> Result<Config, Failure> {
    let input_file = parsed
        .input_file
        .clone()
        .expect("clap guarantees the required option");
    if !std::path::Path::new(&input_file).is_file() {
        return Err(Failure::Cli("'inputFile' does not exist".to_string()));
    }
    let workers = match num_field(parsed, ArgId::Workers) {
        Some(w) => w,
        None => DEFAULT_WORKERS,
    };
    if workers == 0 {
        return Err(Failure::Cli("'workers' must be positive".to_string()));
    }
    let min_len = match num_field(parsed, ArgId::MinLen) {
        Some(v) => v,
        None => 1,
    };
    if min_len == 0 {
        return Err(Failure::Cli("'minPasswordLen' must be positive".to_string()));
    }
    let max_len = match num_field(parsed, ArgId::MaxLen) {
        Some(v) => v,
        None => 10,
    };
    if max_len == 0 {
        return Err(Failure::Cli("'maxPasswordLen' must be positive".to_string()));
    }
    if max_len < min_len {
        return Err(Failure::Cli(
            "'maxPasswordLen' must be equal or greater than 'minPasswordLen'".to_string(),
        ));
    }
    let dictionary = match &parsed.dictionary {
        Some(p) => {
            if !std::path::Path::new(p).is_file() {
                return Err(Failure::Cli("'passwordDictionary' does not exist".to_string()));
            }
            Some(p.clone())
        }
        None => None,
    };
    let charset_file = match &parsed.charset_file {
        Some(p) => {
            if !std::path::Path::new(p).is_file() {
                return Err(Failure::Cli("'charsetFile' does not exist".to_string()));
            }
            Some(p.clone())
        }
        None => None,
    };
    if dictionary.is_some() && parsed.start.is_some() {
        return Err(Failure::Cli(
            "'startingPassword' cannot be used with a dictionary file".to_string(),
        ));
    }
    let mut charset: Vec<char> = Vec::new();
    if dictionary.is_none() {
        match &charset_file {
            Some(path) => match std::fs::read_to_string(path) {
                Ok(contents) => charset = password_gen::charset_from_file(&contents),
                Err(e) => return Err(Failure::Io(e)),
            },
            None => {
                let spec = parsed.charset.clone().unwrap_or_else(|| "lud".to_string());
                match password_gen::charset_from_options(&spec) {
                    Ok(chars) => charset = chars,
                    Err(option) => {
                        return Err(Failure::Cli(format!("Unknown charset option '{}'", option)))
                    }
                }
            }
        }
    }
    if let Some(start) = &parsed.start {
        if dictionary.is_none() {
            for c in start.chars() {
                if !charset.contains(&c) {
                    return Err(Failure::Cli(
                        "'startingPassword' uses characters out of the generation charset"
                            .to_string(),
                    ));
                }
            }
            let len = start.chars().count();
            if len < min_len || len > max_len {
                return Err(Failure::Cli(
                    "'startingPassword' does not respect 'max_password_len' or 'min_password_len' configuration"
                        .to_string(),
                ));
            }
        }
    }
    let file_number = num_field(parsed, ArgId::FileNumber).unwrap_or(0);
    Ok(Config {
        input_file,
        workers,
        dictionary,
        charset,
        min_len,
        max_len,
        file_number,
        start: parsed.start.clone(),
    })
}

/// Reads the dictionary as lossy UTF-8 lines, mirroring the original reader.
fn read_dictionary(path: &str) -> Result<Arc<Vec<String>>, Failure> {
    let bytes = std::fs::read(path).map_err(Failure::Io)?;
    let text = String::from_utf8_lossy(&bytes).to_string();
    let mut words: Vec<String> = Vec::new();
    for line in text.split('\n') {
        let line = line.strip_suffix('\r').unwrap_or(line);
        words.push(line.to_string());
    }
    Ok(Arc::new(words))
}

enum Msg {
    Progress,
    Found(String),
}

struct Shared {
    cursor: AtomicUsize,
    chunks: usize,
    done: AtomicUsize,
    stop: AtomicBool,
}

fn search_brute_force(
    target: Arc<Target>,
    gen: Arc<PasswordGen>,
    start_index: u128,
    end_index: u128,
    workers: usize,
    min_len: usize,
    max_len: usize,
) -> Option<String> {
    let span = end_index.saturating_sub(start_index);
    if span == 0 {
        return None;
    }
    let chunk = chunk_size(span, workers);
    let chunks = ((span + chunk as u128 - 1) / chunk as u128) as usize;
    let shared = Arc::new(Shared {
        cursor: AtomicUsize::new(0),
        chunks,
        done: AtomicUsize::new(0),
        stop: AtomicBool::new(false),
    });
    let (tx, rx) = mpsc::channel::<Msg>();
    let mut handles = Vec::new();
    for id in 0..workers {
        let shared = shared.clone();
        let target = target.clone();
        let gen = gen.clone();
        let tx = tx.clone();
        let handle = std::thread::Builder::new()
            .name(format!("worker-{}", id + 1))
            .spawn(move || {
                // created up-front so an empty alphabet aborts every worker
                let generator = PasswordGen::new(
                    gen.charset().to_vec(),
                    gen.min_len(),
                    gen.max_len(),
                );
                let _ = &generator;
                loop {
                    if shared.stop.load(Ordering::Relaxed) {
                        break;
                    }
                    let index = shared.cursor.fetch_add(1, Ordering::Relaxed);
                    if index >= shared.chunks {
                        break;
                    }
                    let from = start_index + index as u128 * chunk as u128;
                    let count = ((span - (from - start_index)) as usize).min(chunk);
                    let mut found: Option<String> = None;
                    for offset in 0..count {
                        let candidate = generator.generate(from + offset as u128);
                        if target.verify(candidate.as_bytes()) {
                            found = Some(candidate);
                            break;
                        }
                    }
                    if found.is_some() {
                        shared.stop.store(true, Ordering::Relaxed);
                        let _ = tx.send(Msg::Found(found.unwrap()));
                    } else {
                        let _ = tx.send(Msg::Progress);
                    }
                    let _ = (min_len, max_len);
                    if shared.done.fetch_add(1, Ordering::Relaxed) + 1 >= shared.chunks {
                        break;
                    }
                }
            });
        handles.push(handle);
    }
    drop(tx);
    let mut outcome = None;
    loop {
        match rx.recv() {
            Ok(Msg::Found(p)) => {
                outcome = Some(p);
                break;
            }
            Ok(Msg::Progress) => {}
            Err(_) => break,
        }
    }
    if outcome.is_none() {
        // drain whatever is left so the worker threads can finish
        loop {
            match rx.recv_timeout(Duration::from_millis(0)) {
                Ok(Msg::Found(p)) => {
                    outcome = Some(p);
                    break;
                }
                Ok(Msg::Progress) => continue,
                Err(RecvTimeoutError::Empty) => break,
                Err(RecvTimeoutError::Disconnected) => break,
            }
        }
    }
    for handle in handles {
        let _ = handle.join();
    }
    outcome
}

fn search_dictionary(
    target: Arc<Target>,
    passwords: Arc<Vec<String>>,
    workers: usize,
) -> Option<String> {
    let total = passwords.len();
    if total == 0 {
        return None;
    }
    let chunk = CANDIDATES_PER_UNIT;
    let chunks = (total + chunk - 1) / chunk;
    let shared = Arc::new(Shared {
        cursor: AtomicUsize::new(0),
        chunks,
        done: AtomicUsize::new(0),
        stop: AtomicBool::new(false),
    });
    let (tx, rx) = mpsc::channel::<Msg>();
    let mut handles = Vec::new();
    for id in 0..workers {
        let shared = shared.clone();
        let target = target.clone();
        let passwords = passwords.clone();
        let tx = tx.clone();
        let handle = std::thread::Builder::new()
            .name(format!("worker-{}", id + 1))
            .spawn(move || loop {
                if shared.stop.load(Ordering::Relaxed) {
                    break;
                }
                let index = shared.cursor.fetch_add(1, Ordering::Relaxed);
                if index >= shared.chunks {
                    break;
                }
                let from = index * chunk;
                let to = (from + chunk).min(total);
                let mut found: Option<String> = None;
                for word in &passwords[from..to] {
                    if target.verify(word.as_bytes()) {
                        found = Some(word.clone());
                        break;
                    }
                }
                if found.is_some() {
                    shared.stop.store(true, Ordering::Relaxed);
                    let _ = tx.send(Msg::Found(found.unwrap()));
                } else {
                    let _ = tx.send(Msg::Progress);
                }
                if shared.done.fetch_add(1, Ordering::Relaxed) + 1 >= shared.chunks {
                    break;
                }
            });
        handles.push(handle);
    }
    drop(tx);
    let mut outcome = None;
    loop {
        match rx.recv() {
            Ok(Msg::Found(p)) => {
                outcome = Some(p);
                break;
            }
            Ok(Msg::Progress) => {}
            Err(_) => break,
        }
    }
    if outcome.is_none() {
        loop {
            match rx.recv_timeout(Duration::from_millis(0)) {
                Ok(Msg::Found(p)) => {
                    outcome = Some(p);
                    break;
                }
                Ok(Msg::Progress) => continue,
                Err(RecvTimeoutError::Empty) => break,
                Err(RecvTimeoutError::Disconnected) => break,
            }
        }
    }
    for handle in handles {
        let _ = handle.join();
    }
    outcome
}

/// Chunk length handed to each worker.
fn chunk_size(span: u128, workers: usize) -> usize {
    let per_worker = ((span as u128 + workers as u128 - 1) / workers as u128) as usize;
    let wanted = CANDIDATES_PER_UNIT * workers;
    if per_worker < wanted {
        per_worker.max(1)
    } else {
        wanted
    }
}
