//! Small helper around the archive reader: the archive is opened a second time
//! when a single entry payload is needed.

use crate::zip::{Archive, ZipError};

pub struct ZipReader {
    path: String,
}

impl ZipReader {
    pub fn new(path: &str) -> ZipReader {
        ZipReader { path: path.to_string() }
    }

    /// Payload bytes of `index`, verifying the local file header on the way.
    pub fn payload(&self, index: usize) -> Result<Vec<u8>, ZipError> {
        let archive = Archive::open(&self.path)
                                              .expect("Archive validated before-hand");
        archive.payload(index)
