/// Reads the dictionary as lossy UTF-8 lines, mirroring the original reader.
fn read_dictionary(path: &str) -> Result<Arc<Vec<String>>, Failure> {
    let bytes = std::fs::read(path).map_err(Failure::Io)?;
    let text = String::from_utf8_lossy(&bytes).to_string();
