        done: AtomicUsize::new(0),
        stop: AtomicBool::new(false),
    });
    let (tx, rx) = mpsc::channel::<Msg>();
    let mut handles = Vec::new();
    for id in 0..workers {
        let shared = shared.clone();
        let target = target.clone();
        let gen = gen.clone();
        let tx = tx.clone();
        let handle = std::thread::Builder::new()
            .name(format!("worker-{}", id + 1))
            .spawn(move || {
                // created up-front so an empty alphabet aborts every worker
                let generator = PasswordGen::new(
                    gen.charset().to_vec(),
                    gen.min_len(),
                    gen.max_len(),
                );
                let _ = &generator;
                loop {
                    if shared.stop.load(Ordering::Relaxed) {
                        break;
                    }
                    let index = shared.cursor.fetch_add(1, Ordering::Relaxed);
                    if index >= shared.chunks {
                        break;
                    }
                    let from = start_index + index as u128 * chunk as u128;
                    let count = ((span - (from - start_index)) as usize).min(chunk);
                    let mut found: Option<String> = None;
                    for offset in 0..count {
                        let candidate = generator.generate(from + offset as u128);
                        if target.verify(candidate.as_bytes()) {
                            found = Some(candidate);
                            break;
                        }
                    }
                    if found.is_some() {
                        shared.stop.store(true, Ordering::Relaxed);
                        let _ = tx.send(Msg::Found(found.unwrap()));
                    } else {
                        let _ = tx.send(Msg::Progress);
                    }
                    let _ = (min_len, max_len);
                    if shared.done.fetch_add(1, Ordering::Relaxed) + 1 >= shared.chunks {
                        break;
                    }
