    }
    drop(tx);
    let mut outcome = None;
    loop {
        match rx.recv() {
            Ok(Msg::Found(p)) => {
                outcome = Some(p);
                break;
            }
            Ok(Msg::Progress) => {}
            Err(_) => break,
        }
    }
    if outcome.is_none() {
        // drain whatever is left so the worker threads can finish
        loop {
            match rx.recv_timeout(Duration::from_millis(0)) {
                Ok(Msg::Found(p)) => {
                    outcome = Some(p);
                    break;
                }
                Ok(Msg::Progress) => continue,
                Err(RecvTimeoutError::Empty) => break,
                Err(RecvTimeoutError::Disconnected) => break,
            }
        }
    }
    for handle in handles {
        let _ = handle.join();
    }
    outcome
}

fn search_dictionary(
    target: Arc<Target>,
    passwords: Arc<Vec<String>>,
    workers: usize,
) -> Option<String> {
    let total = passwords.len();
    if total == 0 {
        return None;
    }
    let chunk = CANDIDATES_PER_UNIT;
    let chunks = (total + chunk - 1) / chunk;
    let shared = Arc::new(Shared {
        cursor: AtomicUsize::new(0),
        chunks,
        done: AtomicUsize::new(0),
        stop: AtomicBool::new(false),
    });
    let (tx, rx) = mpsc::channel::<Msg>();
    let mut handles = Vec::new();
    for id in 0..workers {
        let shared = shared.clone();
        let target = target.clone();
        let passwords = passwords.clone();
        let tx = tx.clone();
        let handle = std::thread::Builder::new()
            .name(format!("worker-{}", id + 1))
            .spawn(move || loop {
                if shared.stop.load(Ordering::Relaxed) {
                    break;
                }
                let index = shared.cursor.fetch_add(1, Ordering::Relaxed);
                if index >= shared.chunks {
                    break;
                }
                let from = index * chunk;
                let to = (from + chunk).min(total);
                let mut found: Option<String> = None;
                for word in &passwords[from..to] {
                    if target.verify(word.as_bytes()) {
                        found = Some(word.clone());
                        break;
                    }
                }
                if found.is_some() {
                    shared.stop.store(true, Ordering::Relaxed);
                    let _ = tx.send(Msg::Found(found.unwrap()));
                } else {
                    let _ = tx.send(Msg::Progress);
                }
                if shared.done.fetch_add(1, Ordering::Relaxed) + 1 >= shared.chunks {
                    break;
                }
            });
        handles.push(handle);
    }
    drop(tx);
    let mut outcome = None;
    loop {
        match rx.recv() {
            Ok(Msg::Found(p)) => {
                outcome = Some(p);
                break;
            }
            Ok(Msg::Progress) => {}
            Err(_) => break,
        }
    }
    if outcome.is_none() {
        loop {
            match rx.recv_timeout(Duration::from_millis(0)) {
                Ok(Msg::Found(p)) => {
                    outcome = Some(p);
                    break;
                }
                Ok(Msg::Progress) => continue,
                Err(RecvTimeoutError::Empty) => break,
                Err(RecvTimeoutError::Disconnected) => break,
            }
        }
    }
    for handle in handles {
        let _ = handle.join();
    }
    outcome
}

/// Chunk length handed to each worker.
fn chunk_size(span: u128, workers: usize) -> usize {
    let per_worker = ((span as u128 + workers as u128 - 1) / workers as u128) as usize;
    let wanted = CANDIDATES_PER_UNIT * workers;
    if per_worker < wanted {
        per_worker.max(1)
    } else {
        wanted
    }
}
