//! Helper around the archive reader.
//!
//! The archive is parsed twice by the original program: once while it is being
//! validated (any problem there is reported as a normal error) and a second
//! time when the payload of a single entry is needed.  The second pass trusts
//! the earlier validation and therefore unwraps the result; a malformed local
//! file header is only detected during that pass.
//!
//! Fields that are only present in the local file header (the local name and
//! extra field lengths, and therefore the exact position of the payload) are
//! read together with the payload so that only one pass is required.

use crate::zip::{Archive, ZipError};

/// Fields of the local file header that matter for decryption.
#[derive(Clone, Copy)]
pub struct LocalHeader {
    pub version_needed: u16,
    pub method: u16,
    pub crc: u32,
    pub compressed_size: u64,
    pub uncompressed_size: u64,
    pub extra_len: usize,
}

pub struct ZipReader {
    path: String,
}

impl ZipReader {
    /// Creates a reader for the archive stored at `path`.
    pub fn new(path: &str) -> ZipReader {
        ZipReader { path: path.to_string() }
    }

    /// Reads the local header and the payload of entry `index`.
    ///
    /// The archive is opened again for this; the result is unwrapped because
    /// the archive has already been validated, which means the only errors
    /// that can surface here are the ones the first pass does not look at.
    pub fn entry(&self, index: usize) -> Result<(LocalHeader, Vec<u8>), ZipError> {
        let open_archive = Archive::open(&self.path).expect("Archive validated before-hand");
        let entry = match open_archive.entries.get(index) {
            Some(e) => e,
            None => {
                return Err(ZipError::InvalidArchive("Invalid local file header".to_string()))
            }
        };
        let local = match open_archive.local_fields(index) {
            Some(l) => l,
            None => {
                return Err(ZipError::InvalidArchive("Invalid local file header".to_string()))
            }
        };
        let payload = open_archive.payload(index)?;
        Ok((
            LocalHeader {
                version_needed: local.0,
                method: local.1,
                crc: local.2,
                compressed_size: local.3,
                uncompressed_size: local.4,
                extra_len: local.5,
            },
            payload,
        ))
    }
}
