            return false;
        }
        let body = &data[12..];
        match self.compression_method {
            0 => crc32(body) == self.crc,
            8 => match inflate(body) {
                Ok(plain) => crc32(&plain) == self.crc,
                Err(_) => false,
            },
            _ => false,
        }
    }

