        if self.compression_method != 99 {
            return false;
        }
        match self.encryption {
            Encryption::Aes { method: 0, .. } => {
                // stored: the plaintext length must match the declared size
                let mut plain = ct.to_vec();
                let iv = padded_iv(salt);
                Aes::new(key).ctr(iv, &mut plain);
                plain.len() == self.uncompressed_size as usize
            }
            _ => false,
        }
    }
