/// AES-CTR initial counter block: the salt, right aligned in 16 bytes.
fn padded_iv(salt: &[u8]) -> [u8; 16] {
    let mut iv = [0u8; 16];
    let n = salt.len().min(16);
    iv[..n].copy_from_slice(&salt[..n]);
    iv
}

/// Helper used by the zip reader to verify a CRC incrementally.
pub fn crc32_matches(state: u32, data: &[u8], expected: u32) -> bool {
    let mut c = 0xffff_ffffu32 ^ state;
    for b in data {
        c = crc32_update(c, *b);
    }
    (c ^ 0xffff_ffff) == expected
