use zip_password_finder::crypto::{pbkdf2_sha1, HmacSha1, Aes, crc32};
fn main() {
    // asset 2.test.txt.zip payload
    let payload: Vec<u8> = std::fs::read("/tmp/t/payload2.bin").unwrap();
    let salt = &payload[..8];
    let pv = &payload[8..10];
    let dk = pbkdf2_sha1(b"ab", salt, 1000, 34);
    println!("dk      = {}", dk.iter().map(|b| format!("{:02x}", b)).collect::<String>());
    println!("pv      = {} expected {}", dk[32..34].iter().map(|b| format!("{:02x}", b)).collect::<String>(), pv.iter().map(|b| format!("{:02x}", b)).collect::<String>());
    let key = &dk[..16];
    let mac_key = &dk[16..32];
    let ct = &payload[10..22];
    let auth = &payload[22..32];
    let mac = HmacSha1::new(mac_key).finalize();
    println!("mac     = {}", mac.iter().map(|b| format!("{:02x}", b)).collect::<String>());
    println!("auth    = {}", auth.iter().map(|b| format!("{:02x}", b)).collect::<String>());
    let mut plain = ct.to_vec();
    let mut iv = [0u8;16];
    iv[..8].copy_from_slice(salt);
    Aes::new(key).ctr(iv, &mut plain);
    println!("plain   = {}", plain.iter().map(|b| format!("{:02x}", b)).collect::<String>());
    println!("crc32(x) = {:08x}", crc32(b"Hello World!"));
    // sha1 test vector
    let d = cratecrypto_sha1(b"abc");
    println!("sha1(abc) = {}", d.iter().map(|b| format!("{:02x}", b)).collect::<String>());
}
fn cratecrypto_sha1(data: &[u8]) -> [u8;20] {
    use zip_password_finder::crypto::Sha1;
    Sha1::digest(data)
}
